-- Heroes of Horror class feature definitions.
-- Descriptions are concise mechanical summaries; source pages remain authoritative.
WITH desired(class_slug,feature_slug,name,source_page,description,choice_kind) AS (VALUES
  ('archivist','weapon-armor-proficiency','Weapon and Armor Proficiency','82','Proficient with all simple weapons and light and medium armor, but not shields.',NULL),
  ('archivist','spellcasting','Spellcasting','82-83','Prepare Intelligence-based divine spells from a prayerbook; primarily cleric spells, with noncleric divine spells learnable from divine scrolls.',NULL),
  ('archivist','prayerbook','Prayerbook','83','Maintain a written collection of divine spells; begin with all 0-level cleric spells plus three 1st-level cleric spells and one additional 1st-level cleric spell per Intelligence bonus.',NULL),
  ('archivist','dark-knowledge','Dark Knowledge','83-84','Use an appropriate Knowledge check as a move action to grant allies benefits against aberrations, elementals, magical beasts, outsiders, or undead; uses and available effects scale by archivist level.','other'),
  ('archivist','scribe-scroll','Scribe Scroll','84','Gain Scribe Scroll as a bonus feat.',NULL),
  ('archivist','lore-mastery','Lore Mastery','84','Gain +2 on Decipher Script and one chosen Knowledge skill; later selections add additional Knowledge skills.','other'),
  ('archivist','still-mind','Still Mind','84','Gain +2 on saving throws against enchantment spells and effects.',NULL),
  ('archivist','bonus-feat','Bonus Feat','84','Choose a bonus feat from Skill Focus (a Knowledge skill), Spell Focus, a metamagic feat, or an item creation feat.','feat'),

  ('dread-necromancer','weapon-armor-proficiency','Weapon and Armor Proficiency','85-86','Proficient with simple weapons, one chosen martial weapon, and light armor; not shields. Dread necromancer spells ignore arcane spell failure from light armor.','other'),
  ('dread-necromancer','spellcasting','Spellcasting','85-86','Spontaneously cast Charisma-based arcane spells and automatically know every spell on the dread necromancer list when a new spell level becomes available.',NULL),
  ('dread-necromancer','charnel-touch','Charnel Touch','86','At will, no more than once per round, make a negative-energy melee touch that damages living creatures and heals undead; scaling improves every four class levels.',NULL),
  ('dread-necromancer','rebuke-undead','Rebuke Undead','86','Rebuke or command undead by channeling negative energy as the cleric ability.',NULL),
  ('dread-necromancer','lich-body','Lich Body','86','Gain increasing damage reduction against physical harm as the body moves toward undeath.',NULL),
  ('dread-necromancer','negative-energy-burst','Negative Energy Burst','86','Emit a 5-foot burst of negative energy that damages living creatures and heals undead for 1d4 per class level; Will halves damage to living creatures.',NULL),
  ('dread-necromancer','advanced-learning','Advanced Learning','86','Add an eligible cleric or wizard necromancy spell to the dread necromancer spell list, using the lower spell level when a spell appears on both lists.','spell'),
  ('dread-necromancer','mental-bastion','Mental Bastion','86','Gain a bonus on saves against sleep, stunning, paralysis, poison, and disease.',NULL),
  ('dread-necromancer','fear-aura','Fear Aura','86','As a free action, project a 5-foot fear aura; enemies that fail a Will save become shaken and successful saves grant 24-hour immunity to that dread necromancer''s aura.',NULL),
  ('dread-necromancer','scabrous-touch','Scabrous Touch','86','Imbue charnel touch with a chosen disease as contagion, with no incubation period; activation is a swift action and uses per day scale by level.','other'),
  ('dread-necromancer','summon-familiar','Summon Familiar','86-87','Obtain an imp, quasit, vargouille, or ghostly visage familiar with the listed familiar exceptions.','other'),
  ('dread-necromancer','undead-mastery','Undead Mastery','87','Undead you create gain Strength, Dexterity, and hit point improvements, and your animate dead/control undead capacity scales with Charisma.',NULL),
  ('dread-necromancer','negative-energy-resistance','Negative Energy Resistance','87','Gain +4 on saves against negative-energy effects, including energy drain, some ability drain, and inflict spells.',NULL),
  ('dread-necromancer','fortification','Light Fortification','87','Gain resistance to critical hits that improves at 17th level.',NULL),
  ('dread-necromancer','enervating-touch','Enervating Touch','87','Imbue charnel touch with negative levels; daily negative-level capacity scales by level and increases substantially at 17th.',NULL),
  ('dread-necromancer','craft-wondrous-item','Craft Wondrous Item','87','Gain Craft Wondrous Item as a bonus feat.',NULL),
  ('dread-necromancer','lich-transformation','Lich Transformation','87','At 20th level, a humanoid dread necromancer becomes undead with lich-like class transformation benefits and may create the required phylactery without the normal XP or gold cost.',NULL),

  ('corrupt-avenger','spellcasting','Spellcasting','89-90','Prepare and cast a small Intelligence-style spellbook repertoire of arcane corrupt-avenger spells, while corruption determines access and bonus spells and Charisma determines save DCs.',NULL),
  ('corrupt-avenger','armored-casting','Armored Casting','89','Cast corrupt-avenger spells in light armor without normal arcane spell failure; medium/heavy armor and shields retain normal failure chances.',NULL),
  ('corrupt-avenger','detect-sworn-foe','Detect Sworn Foe','89','Detect the presence, number, strength, and locations of sworn foes over three rounds of concentration in a manner similar to detect evil.',NULL),
  ('corrupt-avenger','sworn-foe','Sworn Foe','89','Choose a specific monster kind or organization; gain scaling bonuses on specified skills involving that foe and enter a corruption-fueled fury when fighting it.','other'),
  ('corrupt-avenger','taint-suppression','Taint Suppression','89','Hide most external signs of physical corruption except while in a tainted area, using internal corruption symptoms as described by the class.',NULL),
  ('corrupt-avenger','tainted-strike','Tainted Strike','89','Infuse a melee attack with taint to add one-half class level to damage against creatures susceptible to taint; uses per day scale by level.',NULL),
  ('corrupt-avenger','grim-resolve','Grim Resolve','90','Add Charisma bonus to saving throws; this does not stack with other abilities that add Charisma to saves.',NULL),
  ('corrupt-avenger','frightful-fury','Frightful Fury','90','When sworn-foe fury begins, nearby opponents that fail a Will save become shaken.',NULL),
  ('corrupt-avenger','unnerving-fury','Unnerving Fury','90','At 9th level, sworn-foe fury can impose a stronger -4 penalty on nearby opponents that fail a Will save.',NULL),

  ('death-delver','spellcasting','Spellcasting','93-94','Prepare Wisdom-based divine death-delver spells as a cleric after nightly contemplation; 0 slots mean bonus spells only.',NULL),
  ('death-delver','deathsense','Deathsense','93','Use a deathwatch-like effect at will as a swift action.',NULL),
  ('death-delver','rebuke-undead','Rebuke Undead','93-94','Rebuke undead as a cleric using death-delver level; compatible previous rebuking levels stack.',NULL),
  ('death-delver','deadened-soul','Deadened Soul','94','Become immune to fear effects.',NULL),
  ('death-delver','spontaneous-casting','Spontaneous Casting','94','Convert prepared spells into cure spells if nonevil, inflict spells if evil, or make a permanent cure/inflict choice if neutral.',NULL),
  ('death-delver','death-ward','Death Ward','94','Use a supernatural death ward effect whose duration is 1 hour per death-delver level; daily uses scale by level.',NULL),
  ('death-delver','diehard','Diehard','94','Gain the benefit of Diehard even without meeting its prerequisites.',NULL),
  ('death-delver','fear-aura','Fear Aura','94','Once per day, emanate a 30-foot fear aura for a number of rounds equal to class level; enemies that fail a Will save are affected as by fear.',NULL),
  ('death-delver','cheat-death','Cheat Death','94','Automatically succeed on Fortitude saves caused by coup de grace and massive damage, though raw damage can still kill you.',NULL),
  ('death-delver','mantle-of-life','Mantle of Life','94','As a full-round action, grant yourself and allies within 60 feet +4 on Will saves for 1 minute per class level.',NULL),
  ('death-delver','nine-lives','Nine Lives','94-95','At 10th level, gain the class''s limited ability to return from otherwise fatal outcomes, subject to its stated use limits and restrictions.',NULL),

  ('dread-witch','master-of-terror','Master of Terror','98','Increase save DCs of fear-descriptor spells by +1, add bane and doom to arcane spell lists as 2nd-level spells, and gain +2 Intimidate per dread-witch level.',NULL),
  ('dread-witch','unnatural-will','Unnatural Will','98','Gain Unnatural Will as a bonus feat even without meeting its prerequisites.',NULL),
  ('dread-witch','absorb-fear','Absorb Fear','98-99','When exposed to fear, convert its severity into temporary caster-level bonuses or an extra low-level spell instead of consuming a spell slot.',NULL),
  ('dread-witch','fearful-empowerment','Fearful Empowerment','98-99','Add the fear descriptor to a visually manifested spell; affected creatures must also save or become shaken for 1d4 rounds.','none'),
  ('dread-witch','delay-fear','Delay Fear','99','Delay the onset of fear effects you impose, and a limited number of times per day delay fear effects affecting you while retaining Absorb Fear benefits.',NULL),
  ('dread-witch','greater-master-of-terror','Greater Master of Terror','99','Increase the fear-spell DC bonus to +2 and allow fear spells to affect normally fear-immune targets unless their Hit Dice exceed caster level by 4 or more.',NULL),
  ('dread-witch','horrific-aura','Horrific Aura','99','Project a 10-foot aura that can shake creatures of 6 HD or less; channel it into a limited horrific touch that can panic creatures and bypass normal fear immunity.',NULL),
  ('dread-witch','reflective-fear','Reflective Fear','99','A fear effect you successfully save against is reflected back at its source, potentially giving other victims another save.',NULL),

  ('fiend-blooded','spellcasting','Spellcasting','103-104','Advance an existing spellcasting class at every fiend-blooded level except 10th.',NULL),
  ('fiend-blooded','fiendish-companion','Fiendish Companion','103-104','A familiar or companion can gain the fiendish template under the class feature''s rules.',NULL),
  ('fiend-blooded','fiendish-heritage','Fiendish Heritage','103-104','Gain a sequence of natural armor and ability-score increases as fiendish ancestry manifests.',NULL),
  ('fiend-blooded','fiendish-sorcery','Fiendish Sorcery','103-104','At each even class level, add an eligible spell known with the fire descriptor or from enchantment, illusion, or necromancy, even if normally divine.','spell'),
  ('fiend-blooded','blood-of-fiends','Blood of Fiends','104','Gain improving resistance to poison and elemental energy from fiendish heritage.',NULL),
  ('fiend-blooded','smiting-spell','Smiting Spell','104','A limited number of times per day, add fiend-blooded level plus Charisma modifier as damage to every target damaged by one spell.',NULL),
  ('fiend-blooded','fiendish-exaltation','Fiendish Exaltation','104','Gain final Strength, Dexterity, Constitution, and Intelligence increases, poison immunity, and damage reduction 10/magic.',NULL),

  ('purifier-hallowed-doctrine','aura-of-purity','Aura of Purity','108','Tainted creatures can recognize the purifier as a threat with a Spot DC that decreases as purifier level rises.',NULL),
  ('purifier-hallowed-doctrine','detect-taint','Detect Taint','108','Use detect taint at will as a spell-like ability.',NULL),
  ('purifier-hallowed-doctrine','turn-undead','Turn Undead','109','Purifier levels stack with cleric or paladin levels for turning undead.',NULL),
  ('purifier-hallowed-doctrine','lay-on-hands','Lay on Hands','109','Lay on hands as a paladin of purifier level; paladin and purifier levels stack.',NULL),
  ('purifier-hallowed-doctrine','smite-taint','Smite Taint','109','Smite tainted creatures as a paladin smites evil; uses per day scale by level and compatible smite uses can be redirected to taint.',NULL),
  ('purifier-hallowed-doctrine','aura-of-sanctity','Aura of Sanctity','109','Allies within 10 feet gain a sacred bonus on saves to resist acquiring taint; bonus improves at 10th level.',NULL),
  ('purifier-hallowed-doctrine','turn-tainted','Turn Tainted','109','Turn a tainted creature as though it were undead with effective turning HD equal to its HD +4.',NULL),
  ('purifier-hallowed-doctrine','purify-soul','Purify Soul','109','Spend a turn-undead use and touch a living creature to remove corruption or depravity without crossing a taint-category boundary; amount removed scales by level.',NULL),
  ('purifier-hallowed-doctrine','cleansing-flame','Cleansing Flame','109','Three times per day, maximize an offensive spell against tainted creatures without increasing spell slot level.',NULL),
  ('purifier-hallowed-doctrine','shield-of-purity','Shield of Purity','109','Spend a turn-undead use to create a 10-foot-radius barrier that tainted creatures cannot enter and that grants +6 sacred saves against their ranged magical attacks.',NULL),

  ('tainted-scholar','spellcasting','Spellcasting','114','Advance an existing arcane spellcasting class at every tainted-scholar level.',NULL),
  ('tainted-scholar','blood-component','Blood Component','114','Take 1 point of damage while casting to substitute your blood as a material component and increase caster level by 1; costly material components are still required.',NULL),
  ('tainted-scholar','level-advancement','Level Advancement','114','Before 10th tainted-scholar level, leaving the class on a level-up requires a Will save with DC 10 + depravity score.',NULL),
  ('tainted-scholar','tainted-spellcasting','Tainted Spellcasting','114','Use depravity instead of the normal key ability for spell access and bonus spells, corruption for spell save DCs, and risk additional depravity whenever casting arcane spells.',NULL),
  ('tainted-scholar','taint-suppression','Taint Suppression','114','Suppress outward signs of physical corruption except while in tainted areas, as described by the class.',NULL),
  ('tainted-scholar','secret','Secret','114-116','At every even class level choose one forbidden secret for which class level plus depravity meets the listed minimum; each secret can be selected only once.','other'),
  ('tainted-scholar','lore','Lore','116','Gain a loremaster-like lore check based on class level and Intelligence for relevant knowledge.',NULL),
  ('tainted-scholar','outre-lore','Outré Lore','116','Gain limited contact-other-plane style access to forbidden information, with taint consequences described by the feature.',NULL),
  ('tainted-scholar','aberrant-lore','Aberrant Lore','116','Gain an expanded supernatural ability to perceive and interpret taint.',NULL),
  ('tainted-scholar','heretical-lore','Heretical Lore','116','Gain the high-level forbidden-lore ability listed for 9th-level tainted scholars.',NULL)
)
INSERT OR IGNORE INTO dnd35_class_features
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,special_ability_id,choice_kind)
SELECT 'hoh-class-feature-'||d.class_slug||'-'||d.feature_slug,'hoh-3.5',d.source_page,
       d.class_slug||'-'||d.feature_slug,d.name,d.description,d.description,0,NULL,1,NULL,d.choice_kind
FROM desired d;
